{
	description = "Evan's dendritic Nix configuration";

	inputs = {
		self.submodules = true;
		nixpkgs.url = "github:NixOS/nixpkgs/nixos-unstable";
		nixpkgs-stable.url = "github:NixOS/nixpkgs/nixos-26.05";
		flake-parts = {
			url = "github:hercules-ci/flake-parts";
			inputs.nixpkgs-lib.follows = "nixpkgs";
		};
		import-tree.url = "github:vic/import-tree";
		nixos-wsl.url = "github:nix-community/NixOS-WSL";
		spotify-nixpkgs.url = "github:NixOS/nixpkgs/9ae611a455b90cf061d8f332b977e387bda8e1ca";
		home-manager = {
			url = "github:nix-community/home-manager";
			inputs.nixpkgs.follows = "nixpkgs";
		};
		mnw.url = "github:Gerg-L/mnw";
		neovim-nightly-overlay.url = "github:nix-community/neovim-nightly-overlay";
		nix-vscode-extensions.url = "github:nix-community/nix-vscode-extensions";
		llm-agents = {
			url = "github:numtide/llm-agents.nix";
			inputs.nixpkgs.follows = "nixpkgs";
		};
	};

	outputs = inputs:
		inputs.flake-parts.lib.mkFlake {
			inherit inputs;
			specialArgs = {
				packagesDir = ./packages;
				dotfilesRoot = ./..;
			};
		} (inputs.import-tree ./modules);
}

{dotfilesRoot, ...}: {
	flake.modules.homeManager.pi = {pkgs, ...}: {
		programs.pi-coding-agent = {
			enable = true;
			extraPackages = with pkgs; [nodejs bun];
		};

		# home.file.".pi".source = dotfilesRoot + "/pi";
	};
}

{dotfilesRoot, ...}: {
	flake.modules.homeManager.dotfiles = {
		config,
		lib,
		pkgs,
		osConfig ? null,
		...
	}: let
		systemPackages =
			if osConfig == null
			then []
			else osConfig.environment.systemPackages;

		availablePackages = config.home.packages ++ systemPackages;

		hasPackage = package:
			lib.any (candidate: lib.getName candidate == lib.getName package) availablePackages;

		linkWhen = condition: directory:
			lib.mkIf condition {
				source = dotfilesRoot + "/${directory}";
			};
	in {
		xdg.configFile = {
			alejandra = linkWhen true "alejandra";
			bat = linkWhen (hasPackage pkgs.bat) "bat";
			delta = linkWhen (config.programs.delta.enable || hasPackage pkgs.delta) "delta";
			erdtree = linkWhen (hasPackage pkgs.erdtree) "erdtree";
			kitty = linkWhen (hasPackage pkgs.kitty) "kitty";
			lazygit = linkWhen (hasPackage pkgs.lazygit) "lazygit";
			# polybar = linkWhen (hasPackage pkgs.polybar) "polybar";
			# tmux = linkWhen (hasPackage pkgs.tmux) "tmux";
			yazi = linkWhen (hasPackage pkgs.yazi) "yazi";
		};
	};
}

{inputs, ...}: {
	flake.modules.homeManager.home-default = {
		imports = [
			inputs.self.modules.homeManager.dotfiles
			# inputs.self.modules.homeManager.cursor
		];
		home.stateVersion = "26.05";
	};
}

{inputs, ...}: {
	flake.modules.homeManager.development = {
		imports = [
			inputs.self.modules.homeManager.cli
			inputs.self.modules.homeManager.direnv
			inputs.self.modules.homeManager.git
			inputs.self.modules.homeManager.neovim
			inputs.self.modules.homeManager.pi
			inputs.self.modules.homeManager.vscode
		];
	};

	perSystem = {pkgs, ...}: let
		neovimDev = inputs.self.homeConfigurations.evanp.config.dotfiles.neovim.finalPackage.devMode;
	in {
		packages.neovim-dev = neovimDev;
		apps.neovim-dev = {
			type = "app";
			program = "${neovimDev}/bin/nvim";
		};
		devShells.default = pkgs.mkShell {packages = [neovimDev];};
	};
}

{inputs, ...}: {
	imports = [inputs.flake-parts.flakeModules.modules];
	systems = ["x86_64-linux"];
}

