README:
# impurity.nix
impurity.nix is a nixos module for creating impure symlinks
to (usually configuraton) files.

### Why
Have you ever stored something like a configuration file you
aren't yet sure of, or a css style you've been tweaking in your
nixos configuration? It's rather slow to repeatedly `nixos-rebuild switch`
the system for every change, as each run usually takes a couple seconds.
impurity.nix allows changes to be made in real time.

Another case is when changing a program's settings through it's settings
interface. Usually if you lock an application's config files into nix, changes
made through the application don't persist as it can't save the files.
impurity.nix allows the application to change its configuration files
*inside* of your nix configuration.

### How
impurity.nix creates an intermediary symlink from the target file to the
corresponding file in your nix configuration. This allows it to be seamlessly
modified by you or the application.

# Usage

### Module Setup
Add impurity to your nixos configuration, specifying the config root, and
create an additional impure system output.

```nix
# flake.nix

{
  inputs.impurity.url = "github:outfoxxed/impurity.nix";

  outputs = { self, nixpkgs, impurity, ... }: {
    nixosConfigurations = {
      example = nixpkgs.lib.nixosSystem {
        modules = [
          {
            imports = [ impurity.nixosModules.impurity ];
            impurity.configRoot = self;
          }

          # ...
        ];

        # ...
      };

      example-impure = self.nixosConfigurations.example.extendModules
        { modules = [ { impurity.enable = true; } ] };
    };
  };
}
```

To create impure symlinks, switch your configuration to the impure output.
You must set the environment variable `IMPURITY_PATH` to your config root.

Note: to access environment variables from a flake evaluation you must pass `--impure`.

Running this command from your config directory will impurely link specified files.
```sh
$ IMPURITY_PATH=$(pwd) sudo --preserve-env=IMPURITY_PATH nixos-rebuild switch --flake --impure .#example-impure
```
An alias or helper script is advised.

Changes made to linked files will be applied to the files inside your configuration. To lock your configuration back to a pure state after changes have been made, just switch to your normal configuration with `impurity.enable` set to `false`.

### Creating Impurity Links
impurity.nix adds an `impurity` attribute to the nixos module arguments.
This means you can directly access it from all modules.

The `link` function provided by the `impurity` attribute creates a direct symlink
when impurity is enabled, or references the path normally otherwise.

Example module:
```nix
{ impurity, ... }: {
  home-manager.users.example-user = {
    xdg.configFile."foobar.conf".source = impurity.link ./foobar.conf;
  };
}
```

`foobar.conf` will be symlinked to the file in your nix config when
`impurity.enable` is true, or interpreted normally when it is false.

### Impurity Groups
Granular groups of impure symlinks may be created via `impurity.groupedLink`.

Example module:
```nix
{ impurity, ... }: {
  home-manager.users.example-user = {
    xdg.configFile."foo.conf".source = impurity.link ./foo.conf;
    xdg.configFile."bar.conf".source = impurity.groupedLink "bar" ./bar.conf;
    xdg.configFile."baz.conf".source = impurity.groupedLink "baz" ./baz.conf;
  };
}
```

When `impurity.enable` is true, `foo.conf` will be unconditionally symlinked.
`bar.conf` and `baz.conf` are both conditionally symlinked based on the `bar` and `baz`
groups respectively.

Impurity groups can be enabled via the `IMPURITY_GROUPS` environment variable. It takes a space separated list of groups, or `*` to enable all groups. Don't forget to pass the `IMPURITY_GROUPS` variable into sudo.

Example command enabling `foo.conf` and `bar.conf` but not `baz.conf`:
```sh
$ IMPURITY_PATH=$(pwd) IMPURITY_GROUPS="bar" sudo --preserve-env=IMPURITY_PATH,IMPURITY_GROUPS nixos-rebuild switch --flake --impure .#example-impure
```

Example command enabling all groups:
```sh
$ IMPURITY_PATH=$(pwd) IMPURITY_GROUPS="*" sudo --preserve-env=IMPURITY_PATH,IMPURITY_GROUPS nixos-rebuild switch --flake --impure .#example-impure
```

{
	config,
	inputs,
	lib,
	...
}: let
	system = "x86_64-linux";
	personality = config.hosts.laptop.personality;
in {
	options.hosts.laptop.personality =
		lib.mkOption {
			type = lib.types.enum ["dwm" "dusk" "kde" "sway"];
			description = "Desktop personality used by the laptop.";
		};

	config = {
		hosts.laptop.personality = lib.mkDefault "dwm";

		flake.modules.nixos.laptop = {
			imports = [
				./_hardware.nix
				inputs.self.modules.nixos."personality-${personality}"
				inputs.self.modules.nixos.gaming
				inputs.self.modules.nixos.evanp
			];
		};

		flake.nixosConfigurations.laptop =
			inputs.nixpkgs.lib.nixosSystem {
				inherit system;
				modules = [
					inputs.home-manager.nixosModules.home-manager
					inputs.self.modules.nixos.laptop
				];
			};
	};
}

{inputs, ...}: {
	flake.modules.nixos.wsl = {pkgs, ...}: {
		imports = with inputs.self.modules.nixos; [
			system-cli
			evanw
			inputs.nixos-wsl.nixosModules.default
		];

		wsl = {
			enable = true;
			defaultUser = "evanw";
		};
		programs.nix-ld.enable = true;
		environment.systemPackages = with pkgs; [
			git
			curl
			wget
			unzip
			zip
			file
			openssh
		];
		system.stateVersion = "26.05";
	};

	flake.nixosConfigurations.wsl =
		inputs.nixpkgs.lib.nixosSystem {
			system = "x86_64-linux";
			modules = [
				inputs.home-manager.nixosModules.home-manager
				inputs.self.modules.nixos.wsl
			];
		};
}

{inputs, ...}: let
	username = "evanp";
in {
	flake.modules.nixos.laptop =
		# Edit this configuration file to define what should be installed on
		# your system.  Help is available in the configuration.nix(5) man page
		# and in the NixOS manual (accessible by running ‘nixos-help’).
		{pkgs, ...}: let
			spotifyPkgs =
				import inputs.spotify-nixpkgs {
					system = pkgs.stdenv.hostPlatform.system;
					config.allowUnfree = true;
				};
			capsToSuperConfig =
				pkgs.writeText "caps-to-super.yaml" (builtins.toJSON {
						TIMING = {
							TAP_MILLISEC = 200;
							DOUBLE_TAP_MILLISEC = 150;
						};
						MAPPINGS = [
							{
								KEY = "KEY_CAPSLOCK";
								TAP = "KEY_LEFTMETA";
								HOLD = "KEY_LEFTMETA";
							}
						];
					});
		in {
			# Bootloader.
			boot.loader.systemd-boot.enable = true;
			boot.loader.efi.canTouchEfiVariables = true;
			# Allow debuggers to attach to other processes owned by the same user.
			boot.kernel.sysctl."kernel.yama.ptrace_scope" = 0;

			networking.hostName = "laptop"; # Define your hostname.
			# networking.wireless.enable = true;  # Enables wireless support via wpa_supplicant.

			# Configure network proxy if necessary
			# networking.proxy.default = "http://user:password@proxy:port/";
			# networking.proxy.noProxy = "127.0.0.1,localhost,internal.domain";

			# Enable networking
			networking.networkmanager.enable = true;

			# Set your time zone.
			time.timeZone = "America/Los_Angeles";

			# Select internationalisation properties.
			i18n.defaultLocale = "en_US.UTF-8";

			i18n.extraLocaleSettings = {
				LC_ADDRESS = "en_US.UTF-8";
				LC_IDENTIFICATION = "en_US.UTF-8";
				LC_MEASUREMENT = "en_US.UTF-8";
				LC_MONETARY = "en_US.UTF-8";
				LC_NAME = "en_US.UTF-8";
				LC_NUMERIC = "en_US.UTF-8";
				LC_PAPER = "en_US.UTF-8";
				LC_TELEPHONE = "en_US.UTF-8";
				LC_TIME = "en_US.UTF-8";
			};

			# Configure keymap in X11
			services.xserver.xkb = {
				layout = "us";
				variant = "";
				options = "";
			};

			services.interception-tools = {
				enable = true;
				plugins = [pkgs.interception-tools-plugins.dual-function-keys];
				udevmonConfig =
					builtins.toJSON [
						{
							JOB = "intercept -g $DEVNODE | dual-function-keys -c ${capsToSuperConfig} | uinput -d $DEVNODE";
							DEVICE.EVENTS.EV_KEY = ["KEY_CAPSLOCK"];
						}
					];
			};

			# Enable CUPS to print documents.
			services.printing.enable = true;

			# Enable sound with pipewire.
			services.pulseaudio.enable = false;
			security.rtkit.enable = true;
			services.pipewire = {
				enable = true;
				alsa.enable = true;
				alsa.support32Bit = true;
				pulse.enable = true;
				# If you want to use JACK applications, uncomment this
				#jack.enable = true;

				# use the example session manager (no others are packaged yet so this is enabled by default,
				# no need to redefine it in your config for now)
				#media-session.enable = true;
			};

			# Enable touchpad support (enabled default in most desktopManager).
			# services.xserver.libinput.enable = true;

			# Define a user account. Don't forget to set a password with ‘passwd’.
			users.users.${username} = {
				isNormalUser = true;
				description = "Evan Porter";
				extraGroups = ["networkmanager" "wheel"];
				# packages = with pkgs; [
				# 	kdePackages.kate
				# 	#  thunderbird
				# ];
				shell = pkgs.fish;
			};

			home-manager = {
				useGlobalPkgs = true;
				useUserPackages = true;
				backupFileExtension = "hm-backup";
			};

			# Fonts configuration
			fonts.packages = with pkgs; [
				# Includes the JetBrainsMonoNL Nerd Font family used by dwm and dmenu.
				nerd-fonts.jetbrains-mono
				nerd-fonts.monaspace
			];
			fonts.fontconfig.defaultFonts.monospace = ["JetBrainsMonoNL Nerd Font"];

			programs.fish.enable = true;
			# Allow unfree packages
			nixpkgs.config.allowUnfree = true;

			# List packages installed in system profile. To search, run:
			# $ nix search wget
			environment.systemPackages = with pkgs; [
				#  vim # Do not forget to add an editor to edit configuration.nix! The Nano editor is also installed by default.
				wget
				tmux
				git
				obsidian
				spotifyPkgs.spotify
				spotatui
				btop
			];

			# Some programs need SUID wrappers, can be configured further or are
			# started in user sessions.
			# programs.mtr.enable = true;
			# programs.gnupg.agent = {
			#   enable = true;
			#   enableSSHSupport = true;
			# };

			# List services that you want to enable:

			# Enable the OpenSSH daemon.
			# services.openssh.enable = true;

			# Open ports in the firewall.
			# networking.firewall.allowedTCPPorts = [ ... ];
			# networking.firewall.allowedUDPPorts = [ ... ];
			# Or disable the firewall altogether.
			# networking.firewall.enable = false;

			# This value determines the NixOS release from which the default
			# settings for stateful data, like file locations and database versions
			# on your system were taken. It‘s perfectly fine and recommended to leave
			# this value at the release version of the first install of this system.
			# Before changing this value read the documentation for this option
			# (e.g. man configuration.nix or on https://nixos.org/nixos/options.html).
			system.stateVersion = "26.05"; # Did you read the comment?

			# dotfiles.defaultTerminal = "st";
		};
}

{inputs, ...}: let
	username = "evanp";
	homeDirectory = "/home/${username}";
in {
	flake.modules.nixos.evanp = {
		users.users.${username} = {
			isNormalUser = true;
			description = "Evan Porter";
			extraGroups = ["networkmanager" "wheel"];
		};
		home-manager.users.${username}.imports = [inputs.self.modules.homeManager.evanp];
	};

	flake.modules.homeManager.evanp = {
		imports = with inputs.self.modules.homeManager; [home-default shell development];
		home = {inherit username homeDirectory;};
	};

	flake.homeConfigurations.${username} =
		inputs.home-manager.lib.homeManagerConfiguration {
			pkgs =
				import inputs.nixpkgs {
					system = "x86_64-linux";
					config.allowUnfree = true;
				};
			modules = [inputs.self.modules.homeManager.${username}];
		};
}

{...}: {
	flake.modules.nixos.nix-settings-base = {
		nix.settings.experimental-features = [
			"nix-command"
			"flakes"
		];
	};
}

{ lib, config, pkgs, ... }: with lib; let
  relativePath = path: assert types.path.check path;
    with builtins; strings.removePrefix (toString config.impurity.configRoot) (toString path);

  impurityGroupEnabled = group: let
    impurityGroups = strings.splitString " " (builtins.getEnv "IMPURITY_GROUPS");
  in group == "*" || builtins.elem group impurityGroups;

  impurePath = let
    impurePathEnv = builtins.getEnv "IMPURITY_PATH";
  in if impurePathEnv == ""
     then throw "impurity.enable is true but IMPURITY_PATH is not set"
     else impurePathEnv;

  createImpurePath = path: let
    relative = (relativePath path);
    full = impurePath + relative;
  in pkgs.runCommand "impurity-${relative}" {} "ln -s ${full} $out";
in {
  options.impurity = {
    enable = mkOption {
      type = types.bool;
      default = false;
      description = "Enable impure symlinks";
    };

    configRoot = mkOption {
      type = types.path;
      description = "The root of your nixos configuration";
    };
  };

  config._module.args.impurity = rec {
    groupedLink = groupspec: path:
      assert types.path.check path; let
        groups =
          if groupspec == null
          then [ "" ]
          else if (types.listOf types.string).check groupspec
               then groupspec
               else assert types.string.check groupspec;
                 strings.splitString " " groupspec;
      in if config.impurity.enable && lists.any (group: impurityGroupEnabled group) groups
         then createImpurePath path
         else path;

    link = path: groupedLink null path;
  };
}

{
  outputs = _: {
    nixosModules = rec {
      impurity = import ./default.nix;
      default = impurity;
    };
  };
}

